"""InvestigationWorkflow: generated by G2C for E2A v1.2; completed by hand.

    route    IntentAgent          stops when the request is UNSUPPORTED
    gather   EvidenceAgent        stops when no record was found
    reason   by intent: InvestigatorAgent (INVESTIGATE, EXPLAIN) | ProposalAgent (PROPOSE)
    execute  ExecutionAgent       only for an actionable proposal; material; pauses for approval

One idempotency claim, taken before the material step and only for an actionable proposal: the
same proposal by the same person is one adjustment. A paused step is stored as a checkpoint (the
ApprovalStore); resume() continues it once a second person with the approver role decides
(four eyes), under the same key, exactly once."""
import hashlib
import json
import logging

from e2a import BaseWorkflow, ResumeRefused, Route, Step, Steps

from ..agents.evidence_agent import EvidenceAgent
from ..agents.execution_agent import ExecutionAgent
from ..agents.intent_agent import IntentAgent
from ..agents.investigator_agent import InvestigatorAgent
from ..agents.proposal_agent import ProposalAgent
from ..services.governance import actionable
from ..services.policy import Policy


class InvestigationWorkflow(BaseWorkflow):
    def __init__(self, agents=None, policy: Policy = None) -> None:
        self.policy = policy or Policy()
        agents = agents or {'IntentAgent': IntentAgent(), 'EvidenceAgent': EvidenceAgent(),
                            'InvestigatorAgent': InvestigatorAgent(),
                            'ProposalAgent': ProposalAgent(self.policy), 'ExecutionAgent': ExecutionAgent()}
        self.agents = agents

    def _build_workflow(self, ctx):
        a = self.agents
        return Steps(
            Step('route', a['IntentAgent'], stop_if=lambda s: s.get('intent', 'UNSUPPORTED') == 'UNSUPPORTED'),
            Step('gather', a['EvidenceAgent'], stop_if=lambda s: not s.get('evidence')),
            Route('reason', by='intent', agents={'INVESTIGATE': a['InvestigatorAgent'],
                                                 'EXPLAIN': a['InvestigatorAgent'], 'PROPOSE': a['ProposalAgent']}),
            Step('execute', a['ExecutionAgent'], when=actionable, material=True),
        )

    @staticmethod
    def _proposal_content(state) -> str:
        # what is proposed, not how the model worded it: the free-text reason differs from one model call to the
        # next, and a different reason must not make the same write-off a second, postable proposal (live finding)
        proposal = {k: v for k, v in (state.get('proposal') or {}).items() if k != 'reason'}
        return json.dumps({'tenant': state.get('tenant_id'), 'user': state.get('user_id'),
                           'line': state.get('line_id'), 'proposal': proposal}, sort_keys=True)

    def _generate_idempotency_key(self, state, ctx) -> str:
        """Without a client Idempotency-Key, the same proposal by the same person is one adjustment."""
        return 'genai-' + hashlib.sha256(self._proposal_content(state).encode()).hexdigest()[:32]

    def _requires_idempotency_claim(self, state, ctx) -> bool:
        return actionable(state)

    def _request_fingerprint(self, state, ctx) -> str:
        return hashlib.sha256(self._proposal_content(state).encode()).hexdigest()

    def _authorize_decision(self, checkpoint, decision, ctx) -> bool:
        """Only an approver decides, and never on their own request (four eyes)."""
        if decision.get('role') != self.policy.approver_role:
            raise ResumeRefused(f"only role '{self.policy.approver_role}' may decide", 'resume',
                                code='DECIDER_REFUSED')
        if self.policy.four_eyes and decision.get('decided_by') == checkpoint.get('requested_by'):
            raise ResumeRefused('four eyes: the requester cannot approve their own adjustment', 'resume',
                                code='DECIDER_REFUSED')
        return True

    def _handle_error(self, error, state, ctx):
        logging.error(f"[InvestigationWorkflow] {error}")
        state["status"] = "FAILED"
        state.setdefault("errors", []).append(str(error))
